query:
query HydrateScrolledShareAssets($shareId: ID!, $ids: [ID!]!, $page: PageInput!, $visibleFieldIds: [ID!]) {
  share(by: {shareId: $shareId}) {
    id
    assets(filter: {assetIds: $ids}, page: $page) {
      nodes {
        id
        ...AssetDetails
        ...AssetFiletype
        ...AssetParent
        ...AssetThumbnail
        ...FieldValues
        ...FolderDetails
        ...FolderThumbnails
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment AssetDetails on Asset {
  id
  assetType
  creator {
    id
    name
    __typename
  }
  identifiedUploader {
    id
    name
    email
    __typename
  }
  fireflyGeneration {
    id
    errorReason
    modelVersion {
      id
      displayName
      __typename
    }
    overallStatus
    __typename
  }
  displayDate
  name
  parent {
    id
    ... on VersionStackAsset {
      displayDate
      parent {
        id
        __typename
      }
      __typename
    }
    __typename
  }
  project {
    id
    __typename
  }
  versionNumber
  unifiedApprovalsOverallApprovalStatus
  __typename
}

fragment AssetFiletype on Asset {
  id
  filetype
  __typename
}

fragment AssetParent on Asset {
  id
  parent {
    id
    ... on VersionStackAsset {
      parent {
        id
        __typename
      }
      __typename
    }
    __typename
  }
  project {
    id
    __typename
  }
  __typename
}

fragment AssetThumbnail on Asset {
  id
  name
  insertedAt
  deletedAt
  isWatermarked
  status
  archiveFrom
  parent {
    id
    __typename
  }
  ...AssetBadges
  ... on AudioAsset {
    media {
      id
      filesize
      __typename
    }
    thumbnailImageUrl {
      url
      __typename
    }
    __typename
  }
  ... on DocumentAsset {
    media {
      id
      filesize
      __typename
    }
    thumbnailImageUrl {
      url
      __typename
    }
    __typename
  }
  ... on ImageAsset {
    thumbnailImageUrl {
      url
      __typename
    }
    media {
      id
      filesize
      metadata {
        id
        originalHeight
        originalWidth
        hasAlpha
        __typename
      }
      __typename
    }
    __typename
  }
  ... on InteractiveAsset {
    thumbnailImageUrl {
      url
      __typename
    }
    media {
      id
      filesize
      __typename
    }
    __typename
  }
  ... on InteractiveLiveAsset {
    thumbnailImageUrl {
      url
      __typename
    }
    media {
      id
      url
      __typename
    }
    __typename
  }
  ... on UnsupportedAsset {
    isInteractiveEligible
    media {
      id
      filesize
      __typename
    }
    __typename
  }
  ... on VideoAsset {
    thumbnailImageUrl {
      url
      __typename
    }
    media {
      id
      filesize
      metadata {
        id
        hasAudio
        __typename
      }
      __typename
    }
    __typename
  }
  ... on ModelAsset {
    thumbnailImageUrl {
      url
      __typename
    }
    media {
      id
      filesize
      __typename
    }
    __typename
  }
  __typename
}

fragment AssetBadges on Asset {
  id
  commentCount
  versionNumber
  ... on AudioAsset {
    media {
      id
      duration
      __typename
    }
    __typename
  }
  ... on DocumentAsset {
    media {
      id
      pageCount
      __typename
    }
    __typename
  }
  ... on VideoAsset {
    media {
      id
      duration
      __typename
    }
    __typename
  }
  ... on ModelAsset {
    media {
      id
      duration
      __typename
    }
    __typename
  }
  __typename
}

fragment FieldValues on Collectible {
  fieldValuesNew(
    page: {first: 1000}
    filters: {fieldDefinitionIds: $visibleFieldIds}
  ) {
    nodes {
      ...FieldValue
      __typename
    }
    __typename
  }
  __typename
}

fragment FieldValue on AssetFieldValue {
  ...DateFieldValue
  ...LongTextFieldValue
  ...MultiSelectFieldValue
  ...NumberFieldValue
  ...RatingFieldValue
  ...SelectFieldValue
  ...TextFieldValue
  ...ToggleFieldValue
  ...UsersFieldValue
  ...UserSingleFieldValue
  ...UserMultiFieldValue
  __typename
}

fragment DateFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on DateFieldValue {
      date
      __typename
    }
    __typename
  }
  __typename
}

fragment FieldValueBase on AssetFieldValue {
  id
  fieldType
  valueLength
  isValueTrimmed
  fieldDefinition {
    id
    __typename
  }
  __typename
}

fragment LongTextFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on LongTextFieldValue {
      longText
      __typename
    }
    __typename
  }
  __typename
}

fragment MultiSelectFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on SelectMultiFieldValue {
      multiSelectedOptions
      __typename
    }
    __typename
  }
  __typename
}

fragment NumberFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on NumberFieldValue {
      number
      __typename
    }
    __typename
  }
  __typename
}

fragment RatingFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on RatingFieldValue {
      rating
      __typename
    }
    __typename
  }
  __typename
}

fragment SelectFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on SelectFieldValue {
      selectedOptions
      __typename
    }
    __typename
  }
  __typename
}

fragment TextFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on TextFieldValue {
      text
      __typename
    }
    __typename
  }
  __typename
}

fragment ToggleFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on ToggleFieldValue {
      toggle
      __typename
    }
    __typename
  }
  __typename
}

fragment UsersFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on UsersFieldValue {
      selectedMembers {
        id
        displayName
        ... on UserSelectMemberValue {
          avatarColor
          color
          displayImageUrl
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment UserSingleFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on UserSingleFieldValue {
      singleSelectedMember {
        id
        displayName
        ... on UserSelectMemberValue {
          color
          displayImageUrl
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment UserMultiFieldValue on AssetFieldValue {
  ...FieldValueBase
  value {
    ... on UserMultiFieldValue {
      multiSelectedMembers {
        id
        displayName
        ... on UserSelectMemberValue {
          color
          displayImageUrl
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment FolderDetails on FolderAsset {
  id
  name
  isRestrictedDescendant
  itemCount
  filesize
  displayDate
  parent {
    id
    __typename
  }
  project {
    id
    __typename
  }
  restricted
  userProvidedColor
  __typename
}

fragment FolderThumbnails on FolderAsset {
  id
  deletedAt
  thumbnails {
    name
    ... on FolderThumbnailFileItem {
      id
      filetype
      thumbnailImageUrl {
        url
        __typename
      }
      __typename
    }
    ... on FolderThumbnailFolderItem {
      id
      fileCount
      __typename
    }
    __typename
  }
  __typename
}
